  "confidence": 0.91,
  "anomalies": [
    {
      "category": "wrong_value",
      "components": ["R54", "R41", "U21"],
      "pins": ["U21.4"],
      "nets": ["VMOT", "NET0052", "GND", "+3V3"],
      "observed": "R54 and R41 are both 50kΩ and form a divider from VMOT to GND. The midpoint, NET0052, feeds U21 AIN0; U21 is powered from +3V3. This divider applies half of VMOT to the ADC input.",
      "expected": "The divider should scale the maximum VMOT voltage so U21's analog input remains within its supply rails. With a 3.3V supply, a half-scale divider exceeds the ADS1115 input absolute maximum once VMOT is above approximately 6.6V.",
      "evidence": [
        {
          "source": "schematic",
          "quote": "VMOT; R54 50k 0.1%; R41 50k 0.1%; NET0052; AIN0; +3V3 — cm4-robot.kicad_sch, page 1"
        },
        {
          "source": "schematic",
          "quote": "D40 SMAJ51A — cm4-robot.kicad_sch, page 1"
        },
        {
          "source": "schematic",
          "quote": "Add I2C ADC for input voltage sensing — cm4-robot.kicad_sch, page 1"
        }
      ],
      "impact": "For VMOT above about 6.6V, the ADC input is driven above its permitted range. This can cause invalid voltage readings and may damage U21 or cause current to flow through its input protection structures.",
      "confidence": 0.91
    }
  ],
  "summary": "The VMOT sensing divider feeds half of VMOT directly to the 3.3V-powered ADS1115, so ordinary motor-supply voltages can exceed the ADC input limit. The shown resistor values do not provide safe scaling for that rail."
}

